import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';

const DMPage = () => {
  const [conversations, setConversations] = useState([]);
  const [selectedConversation, setSelectedConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();


  // Fetch conversations
  useEffect(() => {
    const fetchConversations = async () => {
      try {
        const token = localStorage.getItem('token');
        const res = await fetch('http://localhost:5001/api/conversations', {
          headers: { Authorization: `Bearer ${token}` }
        });

        if (!res.ok) throw new Error('Failed to fetch conversations');

        const { data } = await res.json();
        setConversations(data || []);
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchConversations();
  }, []);

  // Fetch messages when conversation is selected
  useEffect(() => {
    if (!selectedConversation) return;

    const fetchMessages = async () => {
      try {
        const token = localStorage.getItem('token');
        const res = await fetch(
          `http://localhost:5001/api/conversations/${selectedConversation._id}/messages`,
          { headers: { Authorization: `Bearer ${token}` } }
        );

        const { data } = await res.json();
        setMessages(data || []);
      } catch (err) {
        setError(err.message);
      }
    };

    fetchMessages();
  }, [selectedConversation]);

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !selectedConversation) return;

    try {
      const token = localStorage.getItem('token');
      const res = await fetch(
        `http://localhost:5001/api/conversations/${selectedConversation._id}/messages`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`
          },
          body: JSON.stringify({ message: newMessage })
        }
      );

      const { data } = await res.json();
      setMessages([...messages, data]);
      setNewMessage('');
    } catch (err) {
      setError(err.message);
    }
  };

  const handleAcceptApplication = async () => {
    if (!selectedConversation) return;

    try {
      const token = localStorage.getItem('token');
      await fetch(
        `http://localhost:5001/api/conversations/${selectedConversation._id}/accept`,
        {
          method: 'PUT',
          headers: { Authorization: `Bearer ${token}` }
        }
      );

      // Refresh messages to show acceptance notification
      const res = await fetch(
        `http://localhost:5001/api/conversations/${selectedConversation._id}/messages`,
        { headers: { Authorization: `Bearer ${token}` } }
      );
      const { data } = await res.json();
      setMessages(data || []);
    } catch (err) {
      setError(err.message);
    }
  };

  if (loading) return <Loading>Loading conversations...</Loading>;
  if (error) return <Error>Error: {error}</Error>;

  return (
    <Container>
      {/* Left sidebar - Conversation list */}
      <ConversationList>
        <Header>Conversations</Header>
        {conversations.length === 0 ? (
          <EmptyState>No conversations yet</EmptyState>
        ) : (
          <ConversationItems>
            {conversations.map((conv) => {
              const otherUser = conv.participants.find(
                p => p._id !== JSON.parse(localStorage.getItem('user'))._id
              );

              return (
                <ConversationItem 
                  key={conv._id} 
                  active={selectedConversation?._id === conv._id}
                  onClick={() => setSelectedConversation(conv)}
                >
                  <UserAvatar src={otherUser.image || '/default-user.png'} />
                  <ConversationInfo>
                    <UserName>{otherUser.name}</UserName>
                    <Preview>
                      {conv.lastMessage?.message?.substring(0, 30) || 'No messages yet'}...
                    </Preview>
                  </ConversationInfo>
                  {conv.isApplication && conv.status === 'pending' && (
                    <AcceptButton onClick={(e) => {
                      e.stopPropagation();
                      handleAcceptApplication();
                    }}>
                      Accept
                    </AcceptButton>
                  )}
                </ConversationItem>
              );
            })}
          </ConversationItems>
        )}
      </ConversationList>

      {/* Right side - Chat area */}
      <ChatArea>
        {selectedConversation ? (
          <>
            <ChatHeader>
              <ChatTitle>
                {selectedConversation.participants.find(
                  p => p._id !== JSON.parse(localStorage.getItem('user'))._id
                ).name}
              </ChatTitle>
            </ChatHeader>
            <MessagesContainer>
              {messages.length === 0 ? (
                <EmptyState>No messages yet</EmptyState>
              ) : (
                messages.map((msg) => (
                  <Message 
                    key={msg._id} 
                    sent={msg.sender._id === JSON.parse(localStorage.getItem('user'))._id}
                  >
                    <MessageText>{msg.message}</MessageText>
                    <Timestamp>
                      {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </Timestamp>
                  </Message>
                ))
              )}
            </MessagesContainer>
            <MessageInputContainer>
              <MessageInput
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="Type a message..."
                onKeyPress={(e) => e.key === 'Enter' && handleSendMessage()}
              />
              <SendButton onClick={handleSendMessage}>
                <SendIcon>➤</SendIcon>
              </SendButton>
            </MessageInputContainer>
          </>
        ) : (
          <EmptyChat>
            <EmptyState>Select a conversation to start chatting</EmptyState>
          </EmptyChat>
        )}
      </ChatArea>
    </Container>
  );
};
// Glassmorphism styles
const Glasspanel = styled.div`
background: rgba(255, 255, 255, 0.05);
backdrop-filter: blur(10px);
border-radius: 10px;
border: 1px solid rgba(255, 255, 255, 0.1);
box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.36);
`;

// Styled Components
const Container = styled.div`
  display: flex;
  height: 100vh;
  background: var(--bg);
  color: white;
  font-family: 'Segoe UI', sans-serif;
`;

const ConversationList = styled(GlassPanel)`
  width: 350px;
  height: 100%;
  display: flex;
  flex-direction: column;
  border-right: 1px solid rgba(255, 255, 255, 0.1);
`;

const Header = styled.h2`
